CREATE TABLE IF NOT EXISTS harness_runs (id UUID PRIMARY KEY, project_id UUID REFERENCES projects(id), run_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', test_set_version TEXT NOT NULL DEFAULT 'v1', summary JSONB NOT NULL DEFAULT '{}'::jsonb, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS harness_results (id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES harness_runs(id) ON DELETE CASCADE, case_id TEXT NOT NULL, status TEXT NOT NULL, payload JSONB NOT NULL DEFAULT '{}'::jsonb, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS image_generation_jobs (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id), prompt TEXT NOT NULL, prompt_version TEXT NOT NULL DEFAULT 'v1', reference_asset_ids JSONB NOT NULL DEFAULT '[]'::jsonb, citation_ids JSONB NOT NULL DEFAULT '[]'::jsonb, provider TEXT NOT NULL DEFAULT 'chatgpt_browser', status TEXT NOT NULL DEFAULT 'awaiting_confirmation', output_asset_ids JSONB NOT NULL DEFAULT '[]'::jsonb, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), confirmed_at TIMESTAMPTZ, completed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_harness_runs_project_created ON harness_runs(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_image_generation_jobs_project_created ON image_generation_jobs(project_id, created_at DESC);